public static int computeWithHashSet(String s) {
    Set<Character> set = new HashSet<>();
    int left = 0;
    int maxLength = 0;

    for (int right = 0; right < s.length(); right++) {
        while (set.contains(s.charAt(right))) {
            set.remove(s.charAt(left));
            left++;
        }
        set.add(s.charAt(right));
        maxLength = Math.max(maxLength, right - left + 1);
    }
    return maxLength;
}

public static int computeWithHashMap(String s) {
    Map<Character, Integer> map = new HashMap<>();
    int left = 0;
    int maxLength = 0;

    for (int right = 0; right < s.length(); right++) {
        char c = s.charAt(right);
        if (map.containsKey(c) && map.get(c) >= left) {
            left = map.get(c) + 1;
        }
        map.put(c, right);
        maxLength = Math.max(maxLength, right - left + 1);
    }
    return maxLength;
}

public static int computeWithStringBuilder(String s) {
    StringBuilder sb = new StringBuilder();
    int maxLength = 0;

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        int index = sb.indexOf(String.valueOf(c));
        if (index != -1) {
            sb.delete(0, index + 1);
        }
        sb.append(c);
        maxLength = Math.max(maxLength, sb.length());
    }
    return maxLength;
}

public static int computeWithArray(String s) {
    int[] lastIndex = new int[128];
    java.util.Arrays.fill(lastIndex, -1);
    int left = 0;
    int maxLength = 0;

    for (int right = 0; right < s.length(); right++) {
        char c = s.charAt(right);
        if (lastIndex[c] >= left) {
            left = lastIndex[c] + 1;
        }
        lastIndex[c] = right;
        maxLength = Math.max(maxLength, right - left + 1);
    }
    return maxLength;
}
